@php
    $sections = [
        __('Pour commencer') => [
            [__("Qu'est-ce que SagaWyn ?"), __("Un assistant pour le maître de jeu, pensé pour les parties autour d'une vraie table. Il prépare le monde, garde la mémoire de la campagne et distribue l'information aux joueurs, sans remplacer les dés, les figurines ni les discussions.")],
            [__('Faut-il installer quelque chose ?'), __("Non : SagaWyn fonctionne dans un navigateur récent. Vous pouvez aussi l'installer comme une application sur ordinateur, téléphone ou tablette (voir « Configuration recommandée »).")],
            [__('Comment changer la langue, le thème ou la taille du texte ?'), __('Dans « Préférences », en cliquant sur votre nom en haut à droite. Vos choix suivent votre compte sur tous vos appareils.')],
            [__('Quelle différence entre un jeu, un monde et une campagne ?'), __("Le jeu porte vos règles et les champs de vos fiches (caractéristiques, compteurs…). Le monde rassemble les lieux, personnages et organisations, réutilisables d'une campagne à l'autre. La campagne est votre table : scénarios, séances, joueurs et personnages. Plusieurs campagnes peuvent partager un même jeu et un même monde.")],
            [__('Comment découvrir SagaWyn sans rien préparer ?'), __("Dans « Mes campagnes », « Charger la démonstration » crée en un clic « Le Serment de Pierrecendre », dans la langue choisie : un jeu inventé, un monde, un scénario en trois séances, des fiches reliées, une carte avec jetons, des indices, des sons, une séance déjà jouée et un personnage à visiter avec « Voir comme ». Exportez-la ensuite si vous voulez vous en servir comme modèle.")],
            [__('Comment retrouver une fiche rapidement ?'), __("Tapez « / » pour ouvrir la recherche : dans une campagne, elle fouille ses fiches, scènes, règles et documents ; depuis « Mes campagnes », tous vos jeux, mondes et campagnes. Dans un texte, écrivez [[ suivi d'un nom pour créer un lien vers une fiche ; la fiche citée affiche alors « Cité dans » avec tous les endroits qui parlent d'elle.")],
            [__('À quoi servent les tags ?'), __("À classer et filtrer fiches, scènes, règles, documents et sons (« acte 1 », « faction », « à préparer »). La page « Tags » permet de leur donner une couleur, de les renommer et de fusionner deux tags en un seul.")],
            [__('Les joueurs voient-ils mes notes de MJ ?'), __('Jamais. La zone MJ d’une fiche ne quitte pas le serveur pour un joueur : il ne voit que ce que vous lui avez révélé ou donné, et seulement pour son personnage.')],
        ],
        __('Pour le MJ') => [
            [__('Comment inviter mes joueurs ?'), __("Dans la campagne, ouvrez « Membres » et créez un lien d'invitation par joueur. Envoyez-le comme vous voulez (message, Discord, courriel) : le joueur se connecte ou crée son compte, et rejoint la campagne.")],
            [__('Puis-je préparer avec un autre MJ, ou inviter un spectateur ?'), __("Oui. En créant le lien dans « Membres », choisissez le rôle : un co-MJ prépare et mène avec vous, avec accès à la zone MJ, mais ne gère ni les membres ni la suppression de la campagne ; un spectateur ne voit que l'écran de table, en permanence, même quand vous ne le partagez pas aux joueurs : c'est le rôle d'une télé ou d'un projecteur.")],
            [__('Comment attribuer un personnage à un joueur ?'), __('Dans la page « Personnages » de la campagne : créez la fiche ou choisissez un prétiré, puis désignez le joueur. Vous pouvez la réattribuer à tout moment, et joindre la feuille PDF.')],
            [__('Comment révéler une information ou donner un objet ?'), __('Depuis une fiche, un document, une règle ou le mode Session, utilisez « Révéler » ou « Donner » et choisissez les personnages. Ils le reçoivent aussitôt, avec une notification, et tout est noté dans le journal.')],
            [__('Comment préparer un scénario ?'), __("Dans « Scénarios », créez le scénario puis ses scènes, rangées par chapitre. Chaque scène a un statut (prévue, disponible, en cours, jouée), ce qui est prévu et, après la partie, ce qui s'est passé, et rassemble ce qui sert pour la jouer : fiches avec une note courte, documents, règles et sons. Les indices qui la concernent s'affichent à côté.")],
            [__('À quoi sert le mode Session ?'), __("C'est votre écran pendant la partie. Il démarre une séance et affiche la scène en cours avec ses fiches, documents, règles et indices, vos fiches épinglées, la liste « À jouer » (idées et indices à placer, cochés quand c'est fait) et un bloc de notes rattachées à la scène. « Terminer la session » range tout dans la page de la séance, où vous pouvez écrire son résumé.")],
            [__('Puis-je ranger mes écrans à ma façon ?'), __("Oui, la page de la campagne et le mode Session : « Organiser l’écran » fait apparaître une poignée ⠿ sur chaque bloc. Glissez-la (à la souris ou au doigt), ou utilisez les flèches, pour changer l'ordre des blocs et, en mode Session, les passer d'une colonne à l'autre. « Masquer » retire un bloc dont vous ne vous servez pas ; il revient avec « Afficher ». « Disposition par défaut » remet tout en place. Cette disposition est la vôtre, dans toutes vos campagnes : les joueurs et les autres MJ gardent la leur, et rien n'est effacé.")],
            [__('Comment définir les caractéristiques de mon jeu ?'), __("Dans « Champs du jeu », créez les champs des fiches : texte, nombre, liste de choix, compteur (PV, munitions, argent), date, lien, document ou référence à une autre fiche. Chaque champ va en zone publique ou MJ, peut concerner un ou plusieurs types de fiche, et peut être « Modifiable par le joueur » sur son personnage.")],
            [__('Une fiche du monde peut-elle changer dans une seule campagne ?'), __("Oui : sur la fiche, le bloc « Dans cette campagne » garde un statut (vivant, disparu…), des notes et des valeurs de champs propres à la campagne. La fiche du monde et les autres campagnes ne changent pas.")],
            [__('Comment ranger mes règles ?'), __("Les règles du jeu valent pour toutes ses campagnes ; les règles maison n'appartiennent qu'à une campagne. Chacune a une origine (référence, maison, test) et un statut, pour savoir ce qui est adopté et ce qui reste à tester en partie.")],
            [__('Puis-je réutiliser une fiche, un scénario ou une campagne ?'), __("Oui : « Dupliquer » sur une fiche, un scénario ou une campagne en fait une copie. Une campagne dupliquée garde tout le contenu préparé, sans les joueurs, personnages, séances ni journal : pratique pour rejouer un scénario avec une autre table.")],
            [__('Les joueurs peuvent-ils s’échanger des objets ?'), __("Oui, depuis la fiche de leur personnage, ils se donnent objets et connaissances. Par défaut, vous validez chaque échange ; décochez « Valider les échanges entre joueurs » sur la page de la campagne pour les laisser faire et être seulement informé.")],
            [__('Un joueur part : que devient son personnage ?'), __("Dans « Personnages », confiez-le à un autre joueur ou laissez-le sans joueur : il garde tout ce qu'il a reçu. Si le joueur revient, il retrouve son personnage. Un nouveau personnage peut aussi reprendre une partie des connaissances et possessions d'un ancien.")],
            [__('Où relire ce qui s’est passé ?'), __("Le journal de la campagne liste les révélations, dons, échanges et modifications, avec la séance concernée. Chaque séance a sa page avec son résumé, ses notes, ses événements et ce qui a été révélé.")],
            [__('À quoi servent les indices ?'), __("Un indice est une information à part (« Morel travaille pour le Culte »), reliée aux fiches, scènes ou documents concernés. Il apparaît sur ces pages et en mode Session : un clic sur un personnage le lui révèle, un autre clic annule. « Historique des révélations » montre qui a appris quoi, et pendant quelle séance.")],
            [__('Comment vérifier ce qu’un joueur peut voir ?'), __("Sur la page d'un personnage, « Voir comme » affiche exactement ce que son joueur voit, en lecture seule, avec un bandeau pour le rappeler.")],
            [__('Comment montrer une carte ou une image sur la télé ?'), __("En mode Session, ouvrez l'écran de table, glissez la fenêtre sur la télé ou le projecteur et passez en plein écran. Choisissez ensuite ce qui s'affiche ; vous pouvez aussi le partager sur les appareils des joueurs.")],
            [__('Comment utiliser une carte avec une grille et des jetons ?'), __("Dans « Cartes », transformez une image des documents en carte. Vous pouvez y ajouter une grille carrée (taille, alignement, échelle comme « 1 case = 1,5 m »), des jetons liés aux fiches et une règle pour mesurer une distance. Le cadrage choisi est celui de l'écran de table, et un jeton masqué n'y apparaît pas. Vos figurines restent les bienvenues : la carte est un support, pas une table virtuelle.")],
            [__('Comment faire une grande carte de campagne avec des sous-cartes ?'), __("Ouvrez « Carte de campagne » depuis la campagne et choisissez la carte qui sert de vue d'ensemble. En « Placer des points », cliquez sur la carte pour poser un point d'intérêt, puis reliez-le à une sous-carte, une scène ou une fiche. En « Explorer », un clic sur un point ouvre sa sous-carte, qui peut avoir ses propres points, et le fil d'Ariane permet de remonter. Les points reliés à une scène montrent si elle est jouée, en cours ou à venir. Tout reste au MJ : seul le nom d'un point « Visible à la table » s'affiche sur l'écran de table.")],
            [__('Comment lancer une musique pendant la partie ?'), __("Ajoutez vos morceaux dans « Sons » (mp3, ogg, m4a, wav ou flac) et liez-les aux scènes. En mode Session, le bloc « Musique » propose d'abord les sons de la scène en cours : « Ici » les joue sur votre appareil, et la musique continue quand vous changez de page ; « Table » les joue sur l'écran de table, branché sur les enceintes. Au premier morceau, l'écran de table peut demander « Activer le son » : c'est le navigateur qui l'exige.")],
            [__('Comment savoir ce que mes joueurs ont pensé de la partie ?'), __("Ouvrez « Avis des joueurs » depuis la campagne, ou « Demander l'avis des joueurs » sur la page d'une séance. Chaque joueur reçoit une notification et donne une note de 1 à 5 étoiles, ce qui lui a plu et ce qui pourrait être mieux. Si vous cochez « Réponses anonymes », vous voyez les notes et les commentaires sans les noms, et les joueurs le savent avant de répondre.")],
            [__('Puis-je piloter l’écran de table depuis mon téléphone ?'), __("Oui : ouvrez « Télécommande » (depuis le mode Session ou une carte) sur votre téléphone. Vous y videz l'écran, passez à l'élément suivant de la scène, déplacez et zoomez la carte affichée, montrez ou masquez ses jetons.")],
            [__('Comment faire lancer les dés ?'), __("Le bouton « Dés », en bas à gauche de chaque page de la campagne, ouvre le plateau. Touchez un ou plusieurs types de dés (1d20 + 2d6, par exemple), puis choisissez comment les lire : brut (chaque dé tel qu'il tombe, le choix par défaut), additionner, seuil sur le total, seuil par dé, garder les meilleurs ou lire en chiffres, avec des dés qui relancent sur le max (+) ou sur le 1 (−). Le bonus et le seuil peuvent se lire sur la fiche du personnage qui lance (une caractéristique entière, sa dizaine, sa moitié ou son cinquième), et plusieurs bonus nommés (Arme +2) s'ajoutent au même lancer. « Demander » envoie le lancer à toute la table ou à certains personnages, à la vue de tous ou en discret : sans seuil, chaque joueur saisit le sien, et un seuil caché reste chez vous. « Enregistrer ce lancer » le garde pour vous ou pour toute la table ; rechargez-le, modifiez-le, puis « Mettre à jour ». Les lancers à la table s'affichent aussi sur l'écran de table.")],
            [__('Comment voir qui est lié à qui ?'), __("Le « Graphe des relations » dessine les fiches de la campagne et leurs relations. Cliquez sur une fiche pour la mettre au centre, choisissez la profondeur (1 à 3 relations) ou un type de fiche. « Voir comme… » montre le réseau tel qu'un personnage le connaît : seulement les fiches qu'il connaît et les relations publiques entre elles.")],
            [__('À quoi sert la chronologie ?'), __("À noter l'histoire du monde, les événements prévus et ce qui s'est passé en jeu, avec des dates libres (« 12 mars 1924 », « Jour 3 », « Nuit 2 »). Un événement joué noté pendant une séance est rattaché à la séance et à la scène en cours. Cochez « Visible des joueurs » pour qu'ils le lisent.")],
            [__('Où voir ce que le MJ vient de me révéler ?'), __("Ça s'affiche tout seul, dans une fenêtre sur la page où vous êtes, avec le contenu. Si vous n'étiez pas connecté, la fenêtre s'ouvre à votre prochaine visite. Tout reste ensuite sur la page de votre personnage.")],
            [__('Puis-je sauvegarder ma campagne ou la confier à quelqu’un ?'), __("Oui : en bas de la page de la campagne, « Exporter la campagne » télécharge une archive .zip avec le jeu, le monde, les fiches, scénarios, documents, cartes, indices et la chronologie, fichiers compris. Le propriétaire peut aussi « Télécharger la sauvegarde complète », qui ajoute la table : personnages, ce qu'ils ont reçu, séances, notes, messages et journal, sans adresse e-mail ni note gardée pour soi. Depuis « Mes campagnes », « Importer une campagne » la recrée, chez vous ou chez un autre MJ ; les personnages y reviennent sans joueur, prêts à être confiés. Le formulaire d'import indique la taille maximale acceptée par le serveur : une archive plus lourde demande d'augmenter « upload_max_filesize » et « post_max_size » dans la configuration PHP.")],
            [__('Puis-je retirer des fonctions dont ma table n’a pas besoin ?'), __("Oui : sur la page de la campagne, bloc « Fonctions de la campagne », décochez l'écran de table, les cartes, les échanges entre joueurs, le graphe, la chronologie ou l'assistant IA. La fonction disparaît pour tous les membres, sans rien effacer, et revient telle quelle dès que vous la recochez.")],
            [__('Puis-je importer le contenu d’un livre de jeu ou d’un scénario ?'), __("Oui, avec l'IA de votre choix : dans « Importer », ouvrez « Préparez les fichiers avec une IA », copiez le prompt et collez-le dans votre IA avec le PDF. Elle prépare les fichiers à importer (champs, fiches, règles, scènes) et un guide pas à pas. Utilisez uniquement des documents que vous possédez.")],
            [__('Comment partager ma façon d’organiser les fiches ?'), __("Dans « Champs du jeu », « Exporter le modèle » télécharge la structure seule : types de fiche, champs et étiquettes, avec les règles du jeu si vous le souhaitez, sans aucun contenu. Un autre MJ l'importe au même endroit, dans son propre jeu ; ce qui existe déjà sous le même nom n'est pas touché.")],
            [__('Comment garder une trace de toute la campagne ?'), __("Ouvrez « Livre des aventures » depuis la campagne : il rassemble les scènes jouées, scénario par scénario, puis les résumés des séances. Sur chaque scène, « Ce qui s’est passé » raconte ce qui a eu lieu à la table ; si elle s'est jouée comme prévu, cochez simplement « Jouée comme prévu ». Vous pouvez garder une version rédigée (par vous ou par une IA, avec votre propre clé) et l'imprimer ou l'enregistrer en PDF.")],
            [__('Comment une IA peut-elle m’aider après une séance ?'), __("Ouvrez « Assistant IA » dans la campagne et choisissez la séance : SagaWyn prépare un texte avec vos notes et le contexte. Collez-le dans l'IA de votre choix, puis collez sa réponse : elle devient des propositions (résumé, événements, relations, statuts, notes, révélations) que vous acceptez, modifiez ou rejetez une à une. SagaWyn n'envoie rien lui-même, et rien ne change sans votre accord.")],
            [__('Puis-je brancher ma propre IA ?'), __("Oui : dans « Préférences », bloc « Assistant IA », choisissez Claude, ChatGPT ou Mistral et collez une clé d'API à votre nom. L'assistant propose alors « Analyser directement », sans copier-coller. Les appels sont facturés par le fournisseur sur votre compte : fixez-y une limite de dépense. La clé est chiffrée, jamais réaffichée ni exportée.")],
            [__('Dois-je tout saisir à la main ?'), __("Non : la page « Importer » accepte des fichiers CSV ou JSON pour créer d'un coup fiches, scènes, règles ou champs. Mais tout peut aussi se faire directement dans l'application.")],
        ],
        __('Votre compte') => [
            [__('Combien coûte SagaWyn ?'), __("Rejoindre une campagne comme joueur est toujours gratuit. Pour mener vos propres campagnes, un essai Premium commence à votre première campagne ; ensuite, la formule gratuite permet de mener une campagne, et Premium lève les limites et donne plus d'espace pour vos fichiers. Les détails sont dans « Préférences ».")],
            [__('Que se passe-t-il à la fin de l’essai ou de Premium ?'), __("Rien n'est effacé. Les fonctions Premium, marquées ✦, se mettent en pause dans vos campagnes, et vos fiches, cartes, messages et fichiers restent là. Tout revient dès le passage à Premium.")],
            [__('Comment changer mon adresse e-mail ou mon mot de passe ?'), __("Dans « Préférences », bloc « Mon compte ». Votre mot de passe actuel est demandé, et l'ancienne adresse est prévenue du changement. Mot de passe oublié : utilisez le lien « Mot de passe oublié ? » de la page de connexion.")],
            [__('Comment protéger mon compte avec la double authentification ?'), __("Dans « Préférences », bloc « Sécurité », activez la double authentification avec une application de votre téléphone (Google Authenticator, Aegis, 1Password…). Gardez les codes de secours affichés à ce moment-là : chacun permet une connexion sans téléphone.")],
            [__('J’ai perdu mon téléphone et mes codes de secours'), __("Écrivez-nous depuis l'adresse e-mail de votre compte : après vérification, l'administrateur retire la double authentification, et vous pourrez la réactiver.")
                .(filled(config('codexflow.legal.email')) ? ' '.__('Adresse : :email.', ['email' => config('codexflow.legal.email')]) : '')],
            [__('Puis-je récupérer ou effacer mes données ?'), __("Oui, dans « Préférences », bloc « Mes données » : « Télécharger mes données » donne tout ce que SagaWyn garde sur vous, et « Supprimer mon compte » efface votre compte, vos campagnes et vos fichiers. Pensez à exporter vos campagnes avant.")],
        ],
        __('Pour les joueurs') => [
            [__('Où trouver la fiche de mon personnage ?'), __('Dans « Mes campagnes », cliquez sur la campagne : vous arrivez directement sur la fiche de votre personnage, avec ses connaissances, ses possessions et vos notes.')],
            [__('Puis-je garder les personnages que je joue ailleurs ?'), __("Oui : « Mes feuilles » (dans le menu en haut) range les personnages que vous jouez hors de SagaWyn, visibles de vous seul. Chacun a sa feuille PDF, un portrait, des champs libres (textes et compteurs à régler avec − et + pendant la partie) et vos notes. Les fichiers comptent dans l'espace de stockage de votre compte.")],
            [__('Puis-je consulter ma fiche sans réseau ?'), __("Oui, une fois l'application installée et votre fiche ouverte au moins une fois sur l'appareil. Hors ligne, vous pouvez régler vos compteurs, modifier les champs que le MJ vous laisse et écrire des notes : tout est envoyé au retour de la connexion. Un compteur reçoit ce que vous avez retiré ou ajouté, donc les changements du MJ sont gardés ; si le MJ a modifié le même champ entre-temps, sa version est gardée et vous êtes prévenu.")],
            [__('Puis-je modifier ma fiche ?'), __("Vous modifiez les champs que le MJ a rendus modifiables, comme vos compteurs (points de vie, munitions, argent). Vous pouvez aussi ajouter un objet ou une connaissance : le MJ en est informé et le valide.")],
            [__('Puis-je prendre des notes et les partager ?'), __("Oui, sur la page de votre personnage. Chaque note se partage avec « Moi seul », « Moi et le MJ », « Certains joueurs (et le MJ) » ou « Toute la table ». Une note « Moi seul » n'est jamais visible du MJ.")],
            [__('Comment écrire au MJ ou aux autres joueurs ?'), __("Avec « Discussion », en bas de l'écran, ou la page « Messages » : écrivez au MJ en privé, à un autre joueur ou à tout le groupe. Vous êtes prévenu des réponses.")],
            [__('Le MJ me demande mon avis : comment répondre ?'), __("Un bandeau sur la page de votre personnage ouvre le formulaire : une note de 1 à 5 étoiles, ce qui vous a plu et ce qui pourrait être mieux. Le formulaire indique si vos réponses sont anonymes.")],
            [__('Puis-je voir les liens entre ce que mon personnage connaît ?'), __("Oui : depuis la page de votre personnage, « Graphe » montre les fiches qu'il connaît et les relations que le MJ a laissées visibles entre elles. « Chronologie » rassemble les événements que le MJ a partagés.")],
            [__('Comment lancer les dés ?'), __("Avec le bouton « Dés », en bas à gauche : composez votre lancer, en mêlant au besoin plusieurs types de dés, ou choisissez un de vos lancers ou un lancer de la campagne, puis « Lancer ». Par défaut, chaque dé s'affiche tel qu'il tombe ; « Additionner » ou un seuil donnent un total ou une réussite. Le bonus peut reprendre une valeur de la fiche de votre personnage, lue au moment du lancer. « Discret » ne le montre qu'au MJ. « Enregistrer ce lancer » le range dans « Mes lancers » : rechargez-le, modifiez-le quand votre personnage évolue, puis « Mettre à jour ». Quand le MJ vous demande un lancer, une fenêtre s'ouvre d'elle-même : indiquez votre seuil ou votre bonus si besoin, et lancez.")],
            [__('Comment être prévenu des révélations et des messages ?'), __("Dans « Notifications », bloc « Sur cet appareil », activez les notifications : vous serez prévenu même quand l'application est fermée.")],
        ],
    ];
@endphp
{{-- Ouverte aux visiteurs : on peut lire l'aide avant de créer un compte. --}}
<x-dynamic-component :component="auth()->check() ? 'layouts.app' : 'layouts.public'" :title="__('Aide')">
    <div @class(['max-w-3xl space-y-6', 'mx-auto px-4 pt-4 pb-16' => auth()->guest()])>
        <div>
            <h1 class="text-2xl font-semibold">{{ __('Aide') }}</h1>
            <p class="mt-1 text-sm text-stone-600">{{ __('Les questions les plus fréquentes. Vous ne trouvez pas la réponse ? Écrivez-nous.') }}</p>
        </div>

        @foreach ($sections as $heading => $questions)
            <section class="rounded-xl border border-stone-200 bg-white p-6 shadow-sm">
                <h2 class="mb-3 font-semibold">{{ $heading }}</h2>
                <div class="divide-y divide-stone-200">
                    @foreach ($questions as [$question, $answer])
                        <details id="{{ \App\Support\PageHelp::anchor($question) }}" class="group scroll-mt-20 py-2">
                            <summary class="cursor-pointer list-none font-medium text-codex marker:hidden">
                                <span class="mr-1 inline-block transition group-open:rotate-90" aria-hidden="true">›</span>{{ $question }}
                            </summary>
                            <p class="mt-2 pl-4 text-stone-700">{{ $answer }}</p>
                        </details>
                    @endforeach
                </div>
            </section>
        @endforeach

        <section class="rounded-xl border border-stone-200 bg-white p-6 shadow-sm">
            <h2 class="mb-2 font-semibold">{{ __('Un problème ?') }}</h2>
            <p class="text-stone-700">{{ __("Si quelque chose ne marche pas comme prévu, dites-le-nous : le message arrive directement à l'équipe, avec la page concernée.") }}</p>
            {{-- Avec ou sans compte : sans compte, le formulaire demande une adresse pour répondre. --}}
            <a href="{{ route('bugs.create') }}" class="btn-primary mt-3 inline-block" @auth wire:navigate @endauth>{{ __('Signaler un problème') }}</a>
        </section>
    </div>

    {{-- Arrivée depuis le « ? » d'un écran : la question visée s'ouvre. --}}
    <script nonce="{{ Vite::cspNonce() }}">
        (() => {
            const question = location.hash && document.getElementById(decodeURIComponent(location.hash.slice(1)));
            if (question instanceof HTMLDetailsElement) {
                question.open = true;
                question.scrollIntoView();
            }
        })();
    </script>
</x-dynamic-component>
